minimal_reproduction:
use serde_json::{json, Value};
#[inline(never)]
fn consume(name: &str, input: Value) -> Value {
    std::hint::black_box(json!({"action": name,"input": input}))
}
fn main() {
    let reference = json!({"grant_id": "grant-123", "grant_revision": 1, "scope_ref": {"kind":"workspace", "id":"workspace-123"}});
    let bound = |name: &str, mut input: Value| {
        input["management_ref"] = reference.clone();
        consume(name, input)
    };
    let first = bound("novels.get", json!({}));
    assert_eq!(first["input"]["management_ref"], reference);
    drop(first);
    let second = bound("novels.get", json!({}));
    assert_eq!(second["input"]["management_ref"], reference);
    for _ in 0..10000 {
        assert_eq!(bound("novels.get", json!({}))["input"]["management_ref"], reference);
    }
    println!("repro passed");
}

explicit_function_control:
use serde_json::{json, Value};
#[inline(never)]
fn consume(name: &str, input: Value) -> Value {
    std::hint::black_box(json!({"action": name,"input": input}))
}
fn main() {
    let reference = json!({"grant_id": "grant-123", "grant_revision": 1, "scope_ref": {"kind":"workspace", "id":"workspace-123"}});
    fn bound(reference: &Value, name: &str, mut input: Value) -> Value {
        input["management_ref"] = reference.clone();
        consume(name, input)
    }
    let first = bound(&reference, "novels.get", json!({}));
    assert_eq!(first["input"]["management_ref"], reference);
    drop(first);
    let second = bound(&reference, "novels.get", json!({}));
    assert_eq!(second["input"]["management_ref"], reference);
    for _ in 0..10000 {
        assert_eq!(bound(&reference, "novels.get", json!({}))["input"]["management_ref"], reference);
    }
    println!("repro passed");
}
